    { key: "order", label: "\u987A\u5E8F", type: "number", min: -1e4, max: 1e4, value: value.order },
    { key: "maxWaitMs", label: "\u6700\u957F\u7B49\u5F85\uFF08\u6BEB\u79D2\uFF09", type: "number", min: 1e3, max: 3e5, value: value.maxWaitMs },
    { key: "template", label: "\u6CE8\u5165\u6A21\u677F", type: "code", rows: 6, value: value.template, required: true }
