// src/extension/ui/pages/summary/coverage.ts
async function summaryCoveragePage(ctx) {
  const state = await ctx.summary.load();
  const range = ctx.memo("summary-coverage-range", () => ({ start: 0, end: lastFloor(), instructions: "" }));
  const target = form([
    ...floorFields(range.start, range.end),
    {
      key: "instructions",
      label: "\u5B9A\u5411\u8865\u5168\u8981\u6C42",
      type: "textarea",
      rows: 3,
      value: range.instructions,
      hint: "\u53EA\u7528\u4E8E\u201C\u751F\u6210\u8865\u5168\u5019\u9009\u201D\uFF0C\u4F8B\u5982\uFF1A\u8865\u5145\u7B2C 40 \u697C\u7684\u65E5\u5E38\u5BF9\u8BDD\u7EC6\u8282\u3002"
    }
  ], { track: false });
  target.node.addEventListener("input", () => Object.assign(range, {
    start: Number(target.control("start").value),
    end: Number(target.control("end").value),
    instructions: target.control("instructions").value
  }));
  const pick2 = (floor) => {
    if (floor < 0) throw new Error("\u539F\u697C\u5C42\u5DF2\u4E0D\u5B58\u5728\uFF0C\u8BF7\u91CD\u65B0\u68C0\u67E5\u3002");
    target.set("start", floor);
    target.set("end", floor);
    Object.assign(range, { start: floor, end: floor });
    target.node.scrollIntoView({ block: "nearest" });
  };
  const result = h("div", "ec-stack");
  const localCheck = async () => {
    ctx.guard();
    const values = target.values();
    const { messages: messages2 } = messageRangeByFloor(values.start, values.end);
    const ids = new Set(messages2.map((message) => message.id));
    const latest = await ctx.summary.load();
    const slices = latest.slices.filter((slice) => slice.batch.state !== "stale" && slice.batch.source?.kind !== "imported" && slice.batch.messageIds.some((id) => ids.has(id)));
    const entries = await window.TavernHelper.getWorldbook(state.worldbookName);
    const memory = entries.some((entry) => entry.extra?.echoes?.kind === "catalog") ? await new WorldbookMemoryStore().inspect(state.worldbookName) : null;
    ctx.guard();
    const report = inspectSummaryCoverage(messages2, slices, memory?.rows.map((row) => row.dataName) ?? []);
    const paging = { page: 0 };
    const regions = h("div");
    const draw = () => {
      const page = paginate(report.regions, paging, 25);
      fill(regions, table([
        { label: "\u697C\u5C42 / \u5B57\u7B26", cell: (region) => `${checkpointFloor(region.messageId)} / ${region.start}\u2013${region.end}` },
        { label: "\u8BCD\u9762\u5339\u914D", cell: (region) => badge(region.matchedRatio === null ? "\u65E0\u6CD5\u8BC4\u4F30" : `${Math.round(region.matchedRatio * 100)}%`, region.warning ? "warning" : "neutral") },
        { label: "\u5E74\u4EFD\u7EBF\u7D22", cell: (region) => region.years.join(" / ") || "\u2014" },
        { label: "\u547D\u540D\u6761\u76EE", cell: (region) => region.names.join(" / ") || "\u2014" },
        { label: "", className: "is-actions", cell: (region) => h(
          "div",
          "ec-row",
          iconButton("\u67E5\u770B\u539F\u6587", "eye", () => {
            const message = messages2.find((item) => item.id === region.messageId);
            modal("\u539F\u6587\u533A\u57DF", [muted("\u8FD9\u662F\u6309\u5B57\u7B26\u5207\u5206\u7684\u533A\u57DF\uFF0C\u4E0D\u662F\u7CBE\u786E\u7684\u8BC1\u636E\u6807\u6CE8\u3002"), code(message.content.slice(region.start, region.end))]);
          }),
          iconButton("\u7528\u6B64\u697C\u5C42\u8865\u5168", "arrow-up", () => pick2(checkpointFloor(region.messageId)))
        ) }
      ], page.items), page.pages > 1 ? pager(paging, page.pages, report.regions.length, draw, "\u4E2A\u533A\u57DF") : null);
    };
    draw();
    fill(
      result,
      stats([
        ["\u8F93\u5165\u6D88\u606F", String(report.inputMessages)],
        ["\u8F93\u5165\u5B57\u7B26", String(report.inputCharacters)],
        ["\u5BF9\u5E94\u5207\u7247", String(report.outputSlices)],
        ["\u4F4E\u5339\u914D\u533A\u57DF", String(report.regions.filter((region) => region.warning).length)]
      ]),
      callout("info", "\u8BCD\u9762\u5339\u914D\u53EA\u7528\u4E8E\u63D0\u793A\u53EF\u80FD\u7684\u9057\u6F0F\uFF0C\u4E0D\u80FD\u636E\u6B64\u65AD\u5B9A\u6F0F\u8BB0\uFF1B\u6765\u6E90\u6309\u6279\u6B21\u5173\u8054\uFF0C\u4E0D\u662F\u5207\u7247\u7684\u7CBE\u786E\u8BC1\u636E\u3002"),
      lazy2("\u8F93\u51FA\u65F6\u95F4\u5206\u5E03", report.timestamps),
      lazy2("\u547D\u540D\u6761\u76EE\u8986\u76D6", report.names),
      regions
    );
  };
  const review = ctx.summary.coverageReview(state);
  const reviewCard2 = review ? (() => {
    const paging = { page: 0 };
    const host = h("div");
    const draw = () => {
      const page = paginate(review.findings, paging, 25);
      fill(host, table([
        { label: "\u697C\u5C42 / \u5B57\u7B26", cell: (finding) => `${checkpointFloor(finding.messageId)} / ${finding.start}\u2013${finding.end}` },
        { label: "\u6A21\u578B\u5EFA\u8BAE", cell: (finding) => finding.reason },
        { label: "", className: "is-actions", cell: (finding) => h(
          "div",
          "ec-row",
          iconButton("\u67E5\u770B\u68C0\u67E5\u65F6\u7684\u8F93\u5165", "eye", () => modal("\u68C0\u67E5\u65F6\u7684\u8F93\u5165", code(finding.text))),
          iconButton("\u7528\u6B64\u697C\u5C42\u8865\u5168", "arrow-up", () => pick2(checkpointFloor(finding.messageId)))
        ) }
      ], review.findings, { empty: "\u8FD9\u6B21\u68C0\u67E5\u6CA1\u6709\u63D0\u51FA\u9057\u6F0F\u5EFA\u8BAE\uFF1B\u8FD9\u4E0D\u4EE3\u8868\u5DF2\u8BC1\u660E\u5B8C\u5168\u8986\u76D6\u3002" }), page.pages > 1 ? pager(paging, page.pages, review.findings.length, draw) : null);
    };
    draw();
    return card("\u6A21\u578B\u68C0\u67E5\u7ED3\u679C", { description: `${formatTime(review.checkedAt)} \xB7 \u7B2C ${review.startFloor}\u2013${review.endFloor} \u697C\u3002\u6D88\u606F\u6216\u5207\u7247\u53D8\u5316\u540E\u9700\u8981\u91CD\u65B0\u68C0\u67E5\u3002` }, host);
  })() : null;
  const draft = ctx.summary.supplementDraft();
  const candidatesCard = draft ? (() => {
    const existing = draft.state.slices.filter((slice) => slice.batch.state !== "stale");
    const selected = new Set(draft.comparisons.filter((item) => !item.duplicate).map((item) => item.index));
    return card(
      "\u8865\u5168\u5019\u9009\u5BA1\u6838",
      { description: "\u5019\u9009\u53EA\u4FDD\u7559\u5728\u672C\u6B21\u4F1A\u8BDD\u3002\u63D0\u4EA4\u540E\u4F5C\u4E3A\u72EC\u7ACB\u7684\u8865\u5168\u6279\u6B21\u5199\u5165\uFF0C\u4E0D\u79FB\u52A8\u68C0\u67E5\u70B9\u3002" },
      table([
        { label: "", cell: (_candidate, index) => checkbox(
          `\u9009\u62E9\u5019\u9009 ${index + 1}`,
          selected.has(index),
          (value) => value ? selected.add(index) : selected.delete(index),
          draft.comparisons[index].duplicate
        ) },
        { label: "\u65F6\u95F4", cell: (candidate) => candidate.timestamp },
        { label: "\u6807\u9898", cell: (candidate) => candidate.title },
        { label: "\u5BF9\u7167", cell: (_candidate, index) => {
          const comparison = draft.comparisons[index];
          return comparison.duplicate ? badge("\u4E0E\u5DF2\u6709\u5207\u7247\u5B8C\u5168\u91CD\u590D", "warning") : comparison.similar.length ? button("\u67E5\u770B\u76F8\u8FD1\u5207\u7247", () => modal("\u76F8\u8FD1\u7684\u5DF2\u6709\u5207\u7247", code(JSON.stringify(comparison.similar.map((item) => existing[item.existingIndex]), null, 2))), { variant: "ghost", small: true }) : badge("\u6CA1\u6709\u76F8\u8FD1\u5207\u7247");
        } },
        { label: "\u6B63\u6587", cell: (candidate) => lazy2("\u5C55\u5F00", candidate.content) }
      ], draft.candidates),
      h(
        "div",
        "ec-row ec-card-foot",
        button("\u4E22\u5F03\u5019\u9009", async () => {
          if (!await confirmAction({ title: "\u4E22\u5F03\u8FD9\u4E9B\u8865\u5168\u5019\u9009\uFF1F", danger: true, confirmLabel: "\u4E22\u5F03" })) return;
          await ctx.summary.discardSupplement();
          await ctx.refresh();
        }, { variant: "danger", icon: "trash" }),
        button("\u8FFD\u52A0\u9009\u4E2D\u7684\u5207\u7247", async () => {
          if (!await confirmAction({
            title: `\u8FFD\u52A0 ${selected.size} \u4E2A\u5019\u9009\uFF1F`,
            cost: true,
            confirmLabel: "\u8FFD\u52A0",
            message: "\u539F\u6709\u5207\u7247\u4FDD\u6301\u4E0D\u53D8\uFF1B\u8FFD\u52A0\u540E\u4F1A\u5355\u72EC\u8C03\u7528\u603B\u7ED3\u7AEF\u70B9\u751F\u6210\u8FD9\u6279\u7684\u6279\u6B21\u603B\u7ED3\u3002"
          })) return;
          await ctx.run("\u63D0\u4EA4\u8865\u5168\u5207\u7247", () => ctx.summary.commitSupplement([...selected]), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", icon: "floppy-disk" })
      )
    );
  })() : null;
  return stack2(
    card(
      "\u8986\u76D6\u68C0\u67E5",
      { description: "\u68C0\u67E5\u6240\u9009\u697C\u5C42\u662F\u5426\u6709\u7ECF\u5386\u6CA1\u6709\u5199\u8FDB\u603B\u7ED3\uFF0C\u5E76\u9488\u5BF9\u9057\u6F0F\u751F\u6210\u8865\u5168\u5019\u9009\u3002" },
      target.node,
      h(
        "div",
        "ec-row ec-card-foot",
        button("\u672C\u5730\u68C0\u67E5", localCheck, { icon: "magnifying-glass" }),
        button("\u6A21\u578B\u6DF1\u5EA6\u68C0\u67E5", async () => {
          const values = target.values();
          ctx.guard();
          const preview2 = await ctx.summary.previewManual(values.start, values.end);
          if (!await confirmAction({
            title: "\u8FDB\u884C\u6A21\u578B\u6DF1\u5EA6\u68C0\u67E5\uFF1F",
            cost: true,
            confirmLabel: "\u68C0\u67E5",
            message: `\u4F1A\u63D0\u4EA4 ${preview2.subRequests?.length ?? 1} \u4E2A\u68C0\u67E5\u8BF7\u6C42\uFF0C\u53EA\u8F93\u51FA\u53EF\u80FD\u9057\u6F0F\u7684\u533A\u57DF\uFF0C\u4E0D\u751F\u6210\u5207\u7247\u3001\u4E0D\u79FB\u52A8\u68C0\u67E5\u70B9\u3002`
          })) return;
          await ctx.run("\u6A21\u578B\u8986\u76D6\u68C0\u67E5", () => ctx.summary.checkCoverage(values.start, values.end), () => ctx.summary.stop());
          await ctx.refresh();
        }, { icon: "robot" }),
        button("\u9884\u89C8\u5B50\u8BF7\u6C42", async () => {
          const values = target.values();
          ctx.guard();
          modal("\u603B\u7ED3\u5B50\u8BF7\u6C42\u9884\u89C8", lazy2("\u697C\u5C42\u8303\u56F4\u3001\u6E05\u6D17\u7ED3\u679C\u4E0E\u5B50\u8BF7\u6C42", await ctx.summary.previewManual(values.start, values.end)), { size: "large" });
        }, { variant: "ghost", icon: "eye" }),
        button("\u751F\u6210\u8865\u5168\u5019\u9009", async () => {
          const values = target.values();
          ctx.guard();
          const preview2 = await ctx.summary.previewManual(values.start, values.end);
          if (!await confirmAction({
            title: "\u751F\u6210\u8865\u5168\u5019\u9009\uFF1F",
            cost: true,
            confirmLabel: "\u751F\u6210",
            message: `\u4F1A\u63D0\u4EA4 ${preview2.subRequests?.length ?? 1} \u4E2A\u603B\u7ED3\u5B50\u8BF7\u6C42\u3002\u7ED3\u679C\u53EA\u8FDB\u5165\u4E0B\u65B9\u7684\u5F85\u5BA1\u6838\u533A\uFF0C\u4E0D\u4FEE\u6539\u539F\u5207\u7247\u548C\u68C0\u67E5\u70B9\u3002`
          })) return;
          await ctx.run("\u5B9A\u5411\u8865\u5168", () => ctx.summary.generateSupplement(values.start, values.end, values.instructions), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", icon: "plus" })
      ),
      result
    ),
    reviewCard2,
    candidatesCard
  );
}

// src/extension/ui/pages/summary/hiding.ts
async function summaryHidingPage(ctx) {
  const state = await ctx.summary.load();
  const status = await ctx.summary.compression.inspect(state);
  const config2 = state.catalog.compression;
  const policy = form([
    {
      key: "enabled",
      label: "\u81EA\u52A8\u9690\u85CF\u5DF2\u603B\u7ED3\u7684\u539F\u6D88\u606F",
      type: "switch",
      value: config2.enabled,
      hint: "\u9690\u85CF\u53EA\u5F71\u54CD\u53D1\u7ED9\u4E3B\u6A21\u578B\u7684\u4E0A\u4E0B\u6587\uFF0C\u6D88\u606F\u672C\u8EAB\u4E0D\u4F1A\u5220\u9664"
    },
    {
      key: "keepRecentMessages",
      label: "\u4FDD\u7559\u6700\u8FD1\u7684\u539F\u6D88\u606F",
      type: "number",
      min: 0,
      max: 1e3,
      value: config2.keepRecentMessages,
      hint: "\u6700\u8FD1\u8FD9\u4E48\u591A\u6761\u6D88\u606F\u59CB\u7EC8\u53EF\u89C1"
    },
    {
      key: "recentBatchCount",
      label: "\u56FA\u5B9A\u6CE8\u5165\u7684\u8FD1\u671F\u6279\u6B21",
      type: "number",
      min: 0,
      max: 100,
      value: config2.recentBatchCount,
      hint: "\u6700\u8FD1\u8FD9\u4E48\u591A\u4E2A\u6279\u6B21\u7684\u603B\u7ED3\u56FA\u5B9A\u6CE8\u5165\uFF0C\u5176\u4F59\u9760\u53EC\u56DE"
    },
    {
      key: "deletionPolicy",
      label: "\u5220\u9664\u603B\u7ED3\u5207\u7247\u65F6",
      type: "select",
      value: config2.deletionPolicy,
      options: [["restore_first", "\u5148\u6062\u590D\u5BF9\u5E94\u7684\u539F\u6D88\u606F"], ["confirm_restore", "\u6BCF\u6B21\u8BE2\u95EE"], ["keep_hidden", "\u539F\u6D88\u606F\u4FDD\u6301\u9690\u85CF"]]
    }
  ]);
  const range = form(floorFields(0, lastFloor()), { track: false });
  return stack2(
    stats([
      ["\u5DF2\u9690\u85CF", String(status.hidden)],
      ["\u56FA\u5B9A\u53EF\u89C1", String(status.pinned)],
      ["\u53EF\u4EE5\u9690\u85CF", String(status.compressible)],
      ["\u603B\u7ED3\u53EC\u56DE", state.catalog.recallEnabled ? "\u5DF2\u542F\u7528" : "\u672A\u542F\u7528"]
    ]),
    status.blockedReason ? callout("warning", status.blockedReason) : null,
    !state.catalog.recallEnabled && config2.enabled ? callout(
      "warning",
      "\u603B\u7ED3\u53EC\u56DE\u672A\u542F\u7528\u65F6\uFF0C\u88AB\u9690\u85CF\u7684\u7ECF\u5386\u4E0D\u4F1A\u518D\u8FDB\u5165\u4E3B\u6A21\u578B\u7684\u4E0A\u4E0B\u6587\u3002",
      button("\u53BB\u542F\u7528", () => ctx.navigate("recall/strategy"), { variant: "ghost", small: true, icon: "arrow-right" })
    ) : null,
    formCard("\u9690\u85CF\u7B56\u7565", policy, async (values) => {
      ctx.guard();
      await ctx.summary.saveCompression({
        enabled: values.enabled,
        keepRecentMessages: values.keepRecentMessages,
        recentBatchCount: values.recentBatchCount,
        deletionPolicy: values.deletionPolicy
      });
      await ctx.refresh();
    }, { scope: "chat", after: h(
      "div",
      "ec-row",
      button("\u91CD\u65B0\u5E94\u7528\u9690\u85CF", async () => {
        ctx.guard();
        const current = await ctx.summary.load();
        const visibility = await ctx.summary.compression.inspectVisibility(current);
        ctx.guard();
        const pinned = visibility.filter((batch) => batch.pinned > 0);
        const unpin = pinned.length > 0 && await choose({
          title: "\u89E3\u9664\u56FA\u5B9A\u53EF\u89C1\uFF1F",
          cancelValue: false,
          message: `${pinned.length} \u4E2A\u6279\u6B21\u4E2D\u6709\u56FA\u5B9A\u53EF\u89C1\u7684\u539F\u6D88\u606F\uFF0C\u901A\u5E38\u6765\u81EA\u6062\u590D\u64CD\u4F5C\u3002\u89E3\u9664\u540E\u4F1A\u6309\u7B56\u7565\u91CD\u65B0\u9690\u85CF\u3002`,
          choices: [{ value: false, label: "\u4FDD\u7559\u56FA\u5B9A\u53EF\u89C1" }, { value: true, label: "\u89E3\u9664\u5E76\u91CD\u65B0\u9690\u85CF", variant: "primary", focus: true }]
        });
        const result = await ctx.run("\u91CD\u65B0\u5E94\u7528\u9690\u85CF", () => unpin ? ctx.summary.compression.recompressBatch(current, pinned.map((batch) => batch.batchId)) : ctx.summary.compression.reconcile(current));
        toast(result.blockedReason ?? `\u5DF2\u5E94\u7528\uFF1A\u9690\u85CF ${result.hidden} \u6761\uFF0C\u56FA\u5B9A\u53EF\u89C1 ${result.pinned} \u6761\u3002`, result.blockedReason ? "warning" : "success");
        await ctx.refresh();
      }, { icon: "arrows-rotate", small: true })
    ) }),
    card(
      "\u6062\u590D\u539F\u6D88\u606F",
      { description: "\u6062\u590D\u540E\u7684\u6D88\u606F\u4F1A\u56FA\u5B9A\u53EF\u89C1\uFF0C\u76F4\u5230\u91CD\u65B0\u5E94\u7528\u9690\u85CF\u5E76\u9009\u62E9\u89E3\u9664\u3002" },
      range.node,
      h(
        "div",
        "ec-row ec-card-foot",
        button("\u6062\u590D\u5168\u90E8", async () => {
          if (!await confirmAction({ title: "\u6062\u590D\u6240\u6709\u7531 Echoes \u9690\u85CF\u7684\u539F\u6D88\u606F\uFF1F", confirmLabel: "\u6062\u590D" })) return;
          ctx.guard();
          await ctx.summary.compression.restoreAll(state);
          await ctx.refresh();
        }, { icon: "eye" }),
        button("\u6062\u590D\u6240\u9009\u8303\u56F4", async () => {
          const values = range.values();
          ctx.guard();
          await ctx.summary.compression.restoreRange(state, values.start, values.end);
          await ctx.refresh();
        }, { variant: "primary", icon: "eye" })
      )
    )
  );
}

