// src/extension/ui/pages/cleaning-editor.ts
init_schemas3();
var OPERATIONS = { extract: "\u4FDD\u7559\u5339\u914D", remove: "\u5220\u9664\u5339\u914D", replace: "\u66FF\u6362" };
function compare2(before, after) {
  let start = 0;
  while (start < before.length && start < after.length && before[start] === after[start]) start++;
  let suffix = 0;
  while (suffix < before.length - start && suffix < after.length - start && before[before.length - suffix - 1] === after[after.length - suffix - 1]) suffix++;
  const render = (text, kind) => h(
    "pre",
    "ec-code",
    text.slice(0, start),
    h(kind, "", text.slice(start, text.length - suffix)),
    suffix ? text.slice(-suffix) : ""
  );
  return h(
    "div",
    "ec-compare",
    h("div", "", h("h4", "", "\u539F\u6587"), render(before, "del")),
    h("div", "", h("h4", "", after ? "\u6E05\u6D17\u540E" : "\u6E05\u6D17\u540E\u4E3A\u7A7A"), render(after, "ins"))
  );
}
function previewRules(rules) {
  const ordered = rules.map((rule, order) => ({ ...rule, order }));
  const range = form(floorFields(Math.max(0, lastFloor() - 3), lastFloor()), { track: false });
  const result = h("div", "ec-stack");
  modal("\u6E05\u6D17\u6548\u679C\u9884\u89C8\uFF08\u672A\u4FDD\u5B58\u7684\u89C4\u5219\uFF09", [range.node, h("div", "ec-row", button("\u751F\u6210\u5BF9\u7167", async () => {
    const { start, end } = range.values();
    const messages2 = messageRangeByFloor(start, end).messages;
    const floors = new Map(indexedChatMessages().map(({ floor, message }) => [message.id, floor]));
    const report = await previewSummaryPreprocess(messages2, ordered);
    const cleaned = new Map(report.messages.map((message) => [message.id, message.content]));
    fill(result, ...messages2.map((message) => {
      const text = cleaned.get(message.id) ?? "";
      return lazy2(
        h(
          "span",
          "",
          `\u7B2C ${floors.get(message.id)} \u697C \xB7 ${message.role === "user" ? "\u4E3B\u6301\u4EBA" : "\u52A9\u624B"} `,
          badge(text === message.content ? "\u672A\u6539\u53D8" : text ? "\u5DF2\u6539\u53D8" : "\u6E05\u6D17\u540E\u4E3A\u7A7A", text === message.content ? "neutral" : "accent")
        ),
        () => h(
          "div",
          "ec-stack",
          compare2(message.content, text),
          ...report.notes.filter((note) => note.messageId === message.id).map((note) => h("p", "ec-muted", `${note.rule}\uFF1A${note.reason}`))
        )
      );
    }));
  }, { icon: "eye", variant: "primary" })), result], { size: "large" });
}
function editRule(item, done, drafts) {
  const target = form([
    { key: "name", label: "\u540D\u79F0", value: item?.name ?? "", required: true },
    { key: "type", label: "\u64CD\u4F5C", type: "select", value: item?.type ?? "remove", options: Object.entries(OPERATIONS) },
    { key: "pattern", label: "\u6B63\u5219\u8868\u8FBE\u5F0F", type: "code", rows: 2, value: item?.pattern ?? "", required: true },
    { key: "flags", label: "\u6807\u5FD7", value: item?.flags ?? "g" },
    { key: "replacement", label: "\u66FF\u6362\u4E3A", value: item?.replacement ?? "" },
    {
      key: "extractionMode",
      label: "\u4FDD\u7559\u7684\u5185\u5BB9",
      type: "select",
      value: item?.extraction?.mode ?? (item ? "auto" : "match"),
      options: [["match", "\u5B8C\u6574\u5339\u914D"], ["group", "\u6307\u5B9A\u6355\u83B7\u7EC4"], ["auto", "\u5168\u90E8\u6355\u83B7\u7EC4\uFF08\u65E0\u7EC4\u65F6\u7528\u5B8C\u6574\u5339\u914D\uFF09"]]
    },
    { key: "group", label: "\u6355\u83B7\u7EC4\u5E8F\u53F7", type: "number", min: 1, max: 99, value: item?.extraction?.group ?? 1 },
    { key: "separator", label: "\u7247\u6BB5\u4E4B\u95F4\u7684\u5206\u9694", type: "textarea", rows: 2, value: item?.extraction?.separator ?? "\n" },
    { key: "user", label: "\u4F5C\u7528\u4E8E\u4E3B\u6301\u4EBA\u6D88\u606F", type: "switch", value: item?.roles.includes("user") ?? true },
    { key: "assistant", label: "\u4F5C\u7528\u4E8E\u52A9\u624B\u6D88\u606F", type: "switch", value: item?.roles.includes("assistant") ?? true }
  ]);
  const sync = () => {
    const type = target.control("type").value;
    target.show("replacement", type === "replace");
    for (const key2 of ["extractionMode", "separator"]) target.show(key2, type === "extract");
    target.show("group", type === "extract" && target.control("extractionMode").value === "group");
  };
  target.control("type").addEventListener("change", sync);
  target.control("extractionMode").addEventListener("change", sync);
  sync();
  const read = () => {
    const values = target.values();
    new RegExp(values.pattern, values.flags);
    return summaryPreprocessRuleSchema.parse({
      id: item?.id ?? uid("rule"),
      name: values.name,
      type: values.type,
      pattern: values.pattern,
      flags: values.flags,
      replacement: values.replacement ?? item?.replacement ?? "",
      extraction: {
        mode: values.extractionMode ?? item?.extraction?.mode ?? "match",
        group: values.group ?? item?.extraction?.group ?? 1,
        separator: values.separator ?? item?.extraction?.separator ?? "\n"
      },
      roles: [...values.user ? ["user"] : [], ...values.assistant ? ["assistant"] : []],
      enabled: item?.enabled ?? true,
      order: item?.order ?? 0
    });
  };
  formModal(item ? `\u7F16\u8F91\u6E05\u6D17\u89C4\u5219 \xB7 ${item.name}` : "\u6DFB\u52A0\u6E05\u6D17\u89C4\u5219", target, () => done(read()), { size: "large", extra: [
    button("\u9884\u89C8\u6548\u679C", () => {
      const draft = read();
      const next = structuredClone(drafts);
      const index = item ? next.findIndex((rule) => rule.id === item.id) : -1;
      if (index < 0) next.push(draft);
      else next[index] = draft;
      previewRules(next);
    }, { variant: "ghost", icon: "eye" })
  ] });
}
function cleaningList(rules, save) {
  return sortable({
    items: rules,
    describe: (rule) => ({ title: rule.name, tag: OPERATIONS[rule.type], note: `/${rule.pattern}/${rule.flags}` }),
    edit: editRule,
    save: (items) => save(items.map((rule, order) => ({ ...rule, order }))),
    toggle: { get: (rule) => rule.enabled, set: (rule, value) => ({ ...rule, enabled: value }) },
    addLabel: "\u6DFB\u52A0\u89C4\u5219",
    extra: (drafts) => [button("\u9884\u89C8\u6548\u679C", () => previewRules(drafts()), { small: true, variant: "ghost", icon: "eye" })],
    emptyText: "\u6CA1\u6709\u6E05\u6D17\u89C4\u5219\uFF0C\u6D88\u606F\u6309\u539F\u6587\u53D1\u9001\u3002"
  });
}

