      { key: "secret", label: current ? "\u65B0\u5BC6\u94A5" : "API \u5BC6\u94A5", type: "password", required: !current, hint: current ? "\u7559\u7A7A\u5219\u4FDD\u7559\u539F\u5BC6\u94A5" : void 0 }
